	('a9f12081-fa3e-4a36-83f4-58a234e393cd', 'e53f57b7-42e8-4bf3-ba10-609f2205ec99', 'Consider coordinate positions: (1) Latitude is measured from the Equator. (2) Longitude is measured from the Prime Meridian. (3) Two places may share a latitude but have different longitudes. (4) Two places may share a longitude but have different latitudes. Select the correct statements.', 'single_mcq', '[{"en": "1 and 2 only", "hi": "केवल 1 और 2"}, {"en": "1, 2 and 3 only", "hi": "केवल 1, 2 और 3"}, {"en": "2, 3 and 4 only", "hi": "केवल 2, 3 और 4"}, {"en": "All four", "hi": "चारों"}]', '{}', 'English: Latitude and longitude use different reference lines. Places can share one coordinate while differing in the other.
Hindi: अक्षांश और देशांतर के संदर्भ अलग हैं। दो स्थानों का एक निर्देशांक समान और दूसरा अलग हो सकता है।', '{}', 'Geography', NULL, 'hard', 'hi', 'published', '2026-11-12 09:43:21.301232+00', '2026-11-12 09:43:53.768219+00', '{}', '{Latitude,Longitude}', 'निर्देशांक स्थिति पर विचार कीजिए: (1) अक्षांश भूमध्य रेखा से मापा जाता है। (2) देशांतर प्रधान मध्याह्न रेखा से मापा जाता है। (3) दो स्थानों का अक्षांश समान लेकिन देशांतर अलग हो सकता है। (4) दो स्थानों का देशांतर समान लेकिन अक्षांश अलग हो सकता है। सही कथन चुनिए।', NULL, NULL, NULL, 'D', 'both'),
	('45d30060-ac1a-4cc0-8c4e-a0229b125e29', 'e53f57b7-42e8-4bf3-ba10-609f2205ec99', 'A place is located at 20°N, 75°E. Which interpretation is correct?', 'single_mcq', '[{"en": "20° north of the Equator and 75° east of the Prime Meridian", "hi": "भूमध्य रेखा से 20° उत्तर और प्रधान मध्याह्न रेखा से 75° पूर्व"}, {"en": "20° south of the Equator and 75° west of the Prime Meridian", "hi": "भूमध्य रेखा से 20° दक्षिण और प्रधान मध्याह्न रेखा से 75° पश्चिम"}, {"en": "20° east of the Equator and 75° north of the Prime Meridian", "hi": "भूमध्य रेखा से 20° पूर्व और प्रधान मध्याह्न रेखा से 75° उत्तर"}, {"en": "20° north of the Prime Meridian and 75° south of the Equator", "hi": "प्रधान मध्याह्न रेखा से 20° उत्तर और भूमध्य रेखा से 75° दक्षिण"}]', '{}', 'English: 20°N means 20 degrees north of the Equator. 75°E means 75 degrees east of the Prime Meridian.
Hindi: 20°N का अर्थ भूमध्य रेखा से 20° उत्तर है। 75°E का अर्थ प्रधान मध्याह्न रेखा से 75° पूर्व है।', '{}', 'Geography', NULL, 'hard', 'hi', 'published', '2026-11-12 09:43:21.301232+00', '2026-11-12 09:43:53.768219+00', '{}', '{Coordinates,Latitude,Longitude}', 'एक स्थान 20°N, 75°E पर स्थित है। इसकी सही व्याख्या क्या है?', NULL, NULL, NULL, 'A', 'both');


